import sys

def flip_sort(n, pairs):
    total_flips = 0
    for i in range(n):
        if i % 2 == 0:  # Front in increasing order
            if pairs[i][0] < pairs[i+1][0]:
                total_flips += 1
        else:  # Front in decreasing order
            if pairs[i][1] <= pairs[i+1][1]:
                total_flips += 1

    if total_flips == n:
        return minimum_flips(n)
    else:
        return -1

def minimum_flips(n):
    if n <= 1:
        return -1
    if n % 2 == 0:
        return n // 2
    else:
        return (n // 2) + 1

