        for u in range(n):
            for v in range(n):
                for i in range(MAX_N):
                    if not is_path_even(u+v-1, i) or not (u+v-1 == u or u+v-1 == v):
                        continue
                    acc = (acc * idea[(u+v-1)%2][i]) % mod
                    idea[(u+v-1)%2][i] = (idea[(u+v-1)%2][i] + acc) % mod
        acc = (acc * 2) % mod

    ans = 0
    for v in range(MAX_N):
        for i in range(v+1):
            if i % 2 == v % 2:
                ans = (ans + idea[v%2][i]) % mod
