import heapq

def dijkstra(n, edges, src):
    dist = [float('inf')] * (n + 1)
    dist[src] = 0
    pq = [(0, src)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in edges[u]:
            if dist[u] - dist[v] + w + v > dist[v]:
                dist[v] = dist[u] - dist[v] + w + v
                heapq.heappush(pq, (dist[v], v))

    return dist

def query(n, edges, u, v):
    rs = dijkstra(n, edges, u)
    return max(0, rs[v] - (n - 1 - rs[v]))

