            ind = query[1] - 1 - N
            if query[0] == 1:
                if left_heap and left_heap[0][0] > ind + B[ind]:
                    results[query[1]] = heappop(left_heap)[1] + B[ind]
            elif query[0] == 2:
                for i in range(ind, query[2]):
