    mod = 1000000007
    dp = [[0 for _ in range(K+1)] for _ in range(N+1)]

    for restriction in restrictions:
        if restriction[0] == 'I':
            L, R = restriction[1], restriction[2]
            for i in range(L, R+1):
                dp[i][min(A[i], max(1, L-2))] = 1
        elif restriction[0] == 'D':
            L, R = restriction[1], restriction[2]
            for i in range(L, R+1):
                dp[i][max(1, A[i] + 1)] = 1

