import sys

def max_gain_from_1_to_n(n, queries):
    parent = [i for i in range(n)]
    depth = [0] * n
    values = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y, value):
        rootX = find(x)
        rootY = find(y)
        if rootX == rootY:
            return value
        if depth[rootX] < depth[rootY]:
            parent[rootX] = rootY
        elif depth[rootX] > depth[rootY]:
            parent[rootY] = rootX
        else:
            parent[rootX] = rootY
            depth[rootY] += 1
        values[rootY] += value
        return max(values[rootX], values[rootY])

    for u, v, value in queries:
        union(u - 1, v - 1, value)
    return values

