MOD = 10**9 + 7

class PowerTree:
    def __init__(self):
        self.parents = {}
        self.values = {}

    def update(self, update):
        _, pi, vi = update
        self.insert(pi, vi)

    def calculate_power(self, u):
        if u == 0:
            return 0
        return (self.values[u] % MOD) * (self.compute_size(u)) % MOD

    def calculate_powers_post_order(self):
        return sorted(list(self.values.values()), reverse=True)

    def compute_size(self, node):
        size = 1
        for child in self.parents[node]:
            size += self.compute_size(child)
        return size

    def insert(self, node, value):
        self.parents[node] = set([node])
        self.values[node] = value

        if node not in self.parents:
            return

        for child in self.parents[node]:
            self.insert(child, value)

    def leaf_size(self, node):
        size = 0
        for child in self.parents[node]:
            size += self.leaf_size(child)
        return 1 + size

    def calculate_powers(self, node):
        if node == 0:
            self.values[node] = self.leaf_size(0)
            return

        self.values[node] = (self.leaf_size(node) * 2) % MOD
        for child in self.parents[node]:
            self.calculate_powers(child)

