class Tree:
    def __init__(self, nodes):
        self.nodes = nodes
        self.parents = [-1] * len(nodes)

        # Initialize the parent sequence for BFS
        for node in nodes:
            self.parents[nodes[node - 1] - 1] = node

    def bfs(self, start):
        # Perform a level-order search starting from the given node
        queue = [(start, 0)]
        while queue:
            node, level = queue.pop(0)
            self.parents[node - 1] = level

            for neighbor in graph[node]:
                if neighbor == self.parents[neighbor - 1]:
                    continue
                queue.append((neighbor, level + 1))

