from collections import defaultdict

def tree_isomorphic_count(graph):
    result = 0
    for node in range(1, len(graph)):
        depth = [0] * (len(graph) + 1)
        total_subtrees = {1: 1}
        depth[1] = 1
        for child in graph[node]:
            current_depth = 0
            for i in range(1, len(graph[node])):
                for child1, child2 in zip(child, graph[child][node]):
                    if (child1, child2) in total_subtrees:
                        current_depth += total_subtrees[(child1, child2)] + 1
                        total_subtrees[1, max(child1, child2)] = current_depth
                    else:
                        total_subtrees[1, max(child1, child2)] = 1 + depth[child1] + depth[child2]
                current_depth += 1
            result = max(max(result, current_depth), total_subtrees[graph[node][node]])
    return result

def main():
    n = int(input())
    graph = defaultdict(list)
    for _ in range(n-1):
        u, v = map(int, input().split())
        graph[u].append(v)
        graph[v].append(u)
    print(tree_isomorphic_count(graph))

if __name__ == "__main__":
    main()
