    time, color = 2, "white"

    def get_link(u):
        return u, 0 if u in parent[u] else max(s_match[son[u]], time)

    time, s_match = 0, [None] * n

    for p2, p3 in zip(*[iter((i-1, ) * (n-1))] * 2):
        if p2 <= p3:
            parent[p2], parent[p3] = p3, p2
            son[p2] += (p3,)
            son[p3] |= (p2,)
            continue

        (link1, l1), (link2, l2), last = get_link(p2), get_link(p3), time
        time = last = max(l1, l2)

        if p3 > p2:
            mappend = _mappend
        else:
            mappend = opbind

        while l1 < l2:
            mappend(l1, s_match[l2], color)
            t, _l2, _ = point(l1[-1])
            mappend(l1, t, color)
            l2 -= _l2

        while l2 < l1:
            mappend(l1, s_match[l2], color)
            t, _l2, _ = point(l2[-1])
            mappend(l2, t, color)
            l1 -= _l2

        for u in link1 - link2:
            son[u] += (link2,)
            s_match[link2].append(link1)

    for _, v in queries:
        if s_match[v][0] == "black":
            yield "black"
        else:
